//! Exact supported delivery signal identities. Never infer tags from names or pixels.
use super::pipeline::Pipeline;use serde::Serialize;
#[derive(Serialize)]pub struct Contract{pub gamut:usize,pub transfer:usize,pub primaries:&'static str,pub transfer_tag:&'static str,pub matrix:&'static str,pub range:&'static str,pub pipe_pixel_format:&'static str,pub output_pixel_format:&'static str,pub pipe_bits:u8,pub output_bits:u8,pub matrix_scale:Option<&'static str>}
pub fn high(q:&Pipeline,format:&str)->Result<Contract,String>{q.validate()?;let (g,t)=if q.enabled{(q.output_gamut,q.output_transfer)}else{(0,1)};let (primaries,matrix_scale)=match g{0=>("bt709","bt709"),1=>("bt2020","bt2020"),_=>return Err("high-bit delivery requires taggable Rec709/Rec2020 output; set output_gamut 0/1 or use floatEXR/TIFF for working/log data".into())};let transfer_tag=match t{0=>"linear",1=>"iec61966-2-1",8=>"bt709",6 if g==1=>"smpte2084",7 if g==1=>"arib-std-b67",_=>return Err("high-bit delivery requires exact linear/sRGB/BT709 or Rec2020PQ/HLG transfer; select supported output or floatEXR/TIFF".into())};let yuv=match format{"hevc10"=>true,"ffv1_16"=>false,_=>return Err("format hevc10/ffv1_16 required".into())};Ok(Contract{gamut:g,transfer:t,primaries,transfer_tag,matrix:if yuv{if g==0{"bt709"}else{"bt2020nc"}}else{"rgb"},range:if yuv{"tv"}else{"pc"},pipe_pixel_format:"rgba64le",output_pixel_format:if yuv{"yuv420p10le"}else{"gbrp16le"},pipe_bits:16,output_bits:if yuv{10}else{16},matrix_scale:if yuv{Some(matrix_scale)}else{None}})}
